#!/usr/bin/env bash
# generate-openspec.sh — Generate OpenSpec feature spec
# Usage: ./generate-openspec.sh --name "<feature>" --epic "<epic>"

set -euo pipefail

NAME=""
EPIC=""

while [[ $# -gt 0 ]]; do
  case "$1" in
    --name) NAME="$2"; shift 2 ;;
    --epic) EPIC="$2"; shift 2 ;;
    *) echo "Unknown: $1"; exit 1 ;;
  esac
done

if [[ -z "$NAME" || -z "$EPIC" ]]; then
  echo "Usage: $0 --name \"<feature>\" --epic \"<epic>\""
  exit 1
fi

SLUG=$(echo "$NAME" | tr '[:upper:]' '[:lower:]' | sed 's/ /-/g')
OUTPUT="spec-${SLUG}.md"

cat > "$OUTPUT" << SPEC
# Feature: $NAME

## Context
- **Epic:** $EPIC
- **Priority:** P1
- **Complexity:** M

## Problem
[What problem does this solve?]

## Solution
[High-level approach]

## Acceptance Criteria
- [ ] Criterion 1
- [ ] Criterion 2
- [ ] Criterion 3

## Technical Notes
[Architecture, dependencies, risks]

## Design
[Links to designs, wireframes, mockups]

## Out of Scope
[What we're explicitly NOT doing]

---

*Generated by product-discovery workflow*
SPEC

echo "✅ OpenSpec generated: $OUTPUT"
